// Generated by `just generate` from `src/plugins/dotclaude/slices/setup/adapters/addons-cmd.ts`. Edit the source and run `just generate`.
// The `addons` command of `dotclaude-setup`: check the tools of the installed dotclaude add-ons.
// It prints the state of each add-on, the global installs to offer, and the project steps.
// It runs the project steps only with `--apply`, and it never runs a global install.

import fs from "node:fs";
import path from "node:path";
import { runProgram } from "../../../kernel/node/process.ts";
import { SETTINGS_FILE } from "../../../kernel/paths.ts";
import { addonReport, installedAddons, planAddons } from "../domain/addons.ts";
import type { Step } from "../domain/types.ts";
import { type Places, readOptional } from "./files.ts";
import type { Io } from "./io.ts";

/**
 * The first line of the `--version` output of `program`, without the program name that some tools print first,
 * or null when it does not run.
 */
const versionOf = (program: string): string | null => {
  let r: ReturnType<typeof runProgram>;
  try {
    r = runProgram(program, ["--version"], {
      stdin: "ignore",
      stdout: "pipe",
      stderr: "ignore",
    });
  } catch {
    return null;
  }
  if (r.exitCode !== 0) return null;
  const line = (r.stdout as Buffer).toString().trim().split("\n")[0] ?? "";
  return line.startsWith(`${program} `) ? line.slice(program.length + 1) : line;
};

/** Run `steps` in `projectDir` in order, and stop at the first failure. Return true when all pass. */
const runSteps = (steps: Step[], projectDir: string, io: Io): boolean => {
  for (const s of steps) {
    io.log(`Add-on: ${s.cmd.join(" ")}`);
    let r: { exitCode: number | null };
    try {
      r = runProgram(s.cmd[0] as string, s.cmd.slice(1), {
        cwd: projectDir,
        stdin: "inherit",
        stdout: "inherit",
        stderr: "inherit",
      });
    } catch (err) {
      io.error((err as Error).message);
      r = { exitCode: 1 };
    }
    if (r.exitCode !== 0) {
      io.error(`Add-on step failed: ${s.label}. Later steps did not run.`);
      return false;
    }
  }
  return true;
};

/** Run the `addons` command and return the exit status. */
export const addonsCommand = async (
  { apply }: { apply: boolean },
  { configDir, projectDir }: Places,
  io: Io,
): Promise<number> => {
  const names = installedAddons(
    await readOptional(
      path.join(configDir, "plugins", "installed_plugins.json"),
    ),
    (await readOptional(path.join(configDir, SETTINGS_FILE)))[
      "enabledPlugins"
    ] as Record<string, unknown> | undefined,
  );
  if (!names.length) {
    io.log("No dotclaude add-on is installed.");
    return 0;
  }
  const plan = planAddons(names, {
    projectDir,
    bun: Bun.version,
    version: versionOf,
    indexBuilt: fs.existsSync(
      path.join(projectDir, ".codegraph", "codegraph.db"),
    ),
  });
  for (const line of addonReport(plan)) io.log(line);
  return apply && !runSteps(plan.steps, projectDir, io) ? 1 : 0;
};
